**`CheckoutPage.tsx`**
```tsx
import React, { useMemo, useState } from "react";
import "./CheckoutPage.css";
import type { Address, CartItem } from "./types";

interface CheckoutPageProps {
  items: CartItem[];
  shippingCost?: number;
  onBackToCart: () => void;
  onPay: (address: Address) => Promise<void> | void;
}

type AddressErrors = Partial<Record<keyof Address, string>>;

const EMPTY_ADDRESS: Address = {
  fullName: "",
  street: "",
  city: "",
  postalCode: "",
  country: "",
  phone: "",
};

function formatPrice(value: number): string {
  return value.toLocaleString(undefined, {
    style: "currency",
    currency: "USD",
  });
}

function validateAddress(address: Address): AddressErrors {
  const errors: AddressErrors = {};

  if (!address.fullName.trim()) errors.fullName = "Full name is required.";
  if (!address.street.trim()) errors.street = "Street address is required.";
  if (!address.city.trim()) errors.city = "City is required.";
  if (!address.postalCode.trim()) {
    errors.postalCode = "Postal code is required.";
  } else if (!/^[A-Za-z0-9\s-]{3,10}$/.test(address.postalCode.trim())) {
    errors.postalCode = "Enter a valid postal code.";
  }
  if (!address.country.trim()) errors.country = "Country is required.";
  if (!address.phone.trim()) {
    errors.phone = "Phone number is required.";
  } else if (!/^[+0-9()\s-]{7,20}$/.test(address.phone.trim())) {
    errors.phone = "Enter a valid phone number.";
  }

  return errors;
}

export default function CheckoutPage({
  items,
  shippingCost = 5.99,
  onBackToCart,
  onPay,
}: CheckoutPageProps) {
  const [address, setAddress] = useState<Address>(EMPTY_ADDRESS);
  const [errors, setErrors] = useState<AddressErrors>({});
  const [isPaying, setIsPaying] = useState(false);
  const [payError, setPayError] = useState<string | null>(null);

  const subtotal = useMemo(
    () => items.reduce((sum, item) => sum + item.unitPrice * item.quantity, 0),
    [items]
  );
  const total = subtotal + (items.length > 0 ? shippingCost : 0);
  const isCartEmpty = items.length === 0;

  function handleChange(field: keyof Address) {
    return (e: React.ChangeEvent<HTMLInputElement>) => {
      setAddress((prev) => ({ ...prev, [field]: e.target.value }));
    };
  }

  async function handlePay(e: React.FormEvent) {
    e.preventDefault();
    setPayError(null);

    const validationErrors = validateAddress(address);
    setErrors(validationErrors);
    if (Object.keys(validationErrors).length > 0 || isCartEmpty) return;

    setIsPaying(true);
    try {
      await onPay(address);
    } catch {
      setPayError("Payment failed. Please try again.");
    } finally {
      setIsPaying(false);
    }
  }

  return (
    <div className="checkout-page">
      <div className="checkout-header">
        <button
          type="button"
          className="back-link"
          onClick={onBackToCart}
          aria-label="Back to cart"
        >
          &larr; Back to cart
        </button>
        <h1>Checkout</h1>
      </div>

      <div className="checkout-layout">
        <section className="cart-summary" aria-labelledby="cart-summary-heading">
          <h2 id="cart-summary-heading">Your order</h2>

          {isCartEmpty ? (
            <p className="empty-cart-message">Your cart is empty.</p>
          ) : (
            <ul className="cart-items-list">
              {items.map((item) => (
                <li key={item.id} className="cart-item">
                  <img
                    src={item.imageUrl}
                    alt={item.name}
                    className="cart-item-image"
                  />
                  <div className="cart-item-details">
                    <span className="cart-item-name">{item.name}</span>
                    <span className="cart-item-qty">Qty: {item.quantity}</span>
                  </div>
                  <span className="cart-item-price">
                    {formatPrice(item.unitPrice * item.quantity)}
                  </span>
                </li>
              ))}
            </ul>
          )}

          <div className="totals">
            <div className="totals-row">
              <span>Subtotal</span>
              <span>{formatPrice(subtotal)}</span>
            </div>
            <div className="totals-row">
              <span>Shipping</span>
              <span>{isCartEmpty ? formatPrice(0) : formatPrice(shippingCost)}</span>
            </div>
            <div className="totals-row totals-row-grand">
              <span>Total</span>
              <span>{formatPrice(total)}</span>
            </div>
          </div>
        </section>

        <section className="address-form-section" aria-labelledby="address-heading">
          <h2 id="address-heading">Delivery address</h2>

          <form className="address-form" onSubmit={handlePay} noValidate>
            <div className="form-field">
              <label htmlFor="fullName">Full name</label>
              <input
                id="fullName"
                type="text"
                value={address.fullName}
                onChange={handleChange("fullName")}
                aria-invalid={Boolean(errors.fullName)}
                aria-describedby={errors.fullName ? "fullName-error" : undefined}
              />
              {errors.fullName && (
                <span id="fullName-error" className="field-error">
                  {errors.fullName}
                </span>
              )}
            </div>

            <div className="form-field">
              <label htmlFor="street">Street address</label>
              <input
                id="street"
                type="text"
                value={address.street}
                onChange={handleChange("street")}
                aria-invalid={Boolean(errors.street)}
                aria-describedby={errors.street ? "street-error" : undefined}
              />
              {errors.street && (
                <span id="street-error" className="field-error">
                  {errors.street}
                </span>
              )}
            </div>

            <div className="form-row">
              <div className="form-field">
                <label htmlFor="city">City</label>
                <input
                  id="city"
                  type="text"
                  value={address.city}
                  onChange={handleChange("city")}
                  aria-invalid={Boolean(errors.city)}
                  aria-describedby={errors.city ? "city-error" : undefined}
                />
                {errors.city && (
                  <span id="city-error" className="field-error">
                    {errors.city}
                  </span>
                )}
              </div>

              <div className="form-field">
                <label htmlFor="postalCode">Postal code</label>
                <input
                  id="postalCode"
                  type="text"
                  value={address.postalCode}
                  onChange={handleChange("postalCode")}
                  aria-invalid={Boolean(errors.postalCode)}
                  aria-describedby={
                    errors.postalCode ? "postalCode-error" : undefined
                  }
                />
                {errors.postalCode && (
                  <span id="postalCode-error" className="field-error">
                    {errors.postalCode}
                  </span>
                )}
              </div>
            </div>

            <div className="form-field">
              <label htmlFor="country">Country</label>
              <input
                id="country"
                type="text"
                value={address.country}
                onChange={handleChange("country")}
                aria-invalid={Boolean(errors.country)}
                aria-describedby={errors.country ? "country-error" : undefined}
              />
              {errors.country && (
                <span id="country-error" className="field-error">
                  {errors.country}
                </span>
              )}
            </div>

            <div className="form-field">
              <label htmlFor="phone">Phone number</label>
              <input
                id="phone"
                type="tel"
                value={address.phone}
                onChange={handleChange("phone")}
                aria-invalid={Boolean(errors.phone)}
                aria-describedby={errors.phone ? "phone-error" : undefined}
              />
              {errors.phone && (
                <span id="phone-error" className="field-error">
                  {errors.phone}
                </span>
              )}
            </div>

            {payError && <p className="pay-error">{payError}</p>}

            <div className="checkout-actions">
              <button
                type="button"
                className="secondary-button"
                onClick={onBackToCart}
                disabled={isPaying}
              >
                Back to cart
              </button>
              <button
                type="submit"
                className="pay-button"
                disabled={isCartEmpty || isPaying}
              >
                {isPaying ? "Processing..." : `Pay ${formatPrice(total)}`}
              </button>
            </div>
          </form>
        </section>
      </div>
    </div>
  );
}
```

