**Example usage (`App.tsx`)**
```tsx
import React from "react";
import CheckoutPage from "./CheckoutPage";
import type { Address, CartItem } from "./types";

const sampleItems: CartItem[] = [
  { id: "1", name: "Wireless Mouse", imageUrl: "/images/mouse.jpg", unitPrice: 29.99, quantity: 1 },
  { id: "2", name: "Mechanical Keyboard", imageUrl: "/images/keyboard.jpg", unitPrice: 89.99, quantity: 1 },
];

export default function App() {
  function handleBackToCart() {
    console.log("Navigate back to cart");
  }

  async function handlePay(address: Address) {
    console.log("Paying with address:", address);
    await new Promise((resolve) => setTimeout(resolve, 1200));
  }

  return (
    <CheckoutPage
      items={sampleItems}
      onBackToCart={handleBackToCart}
      onPay={handlePay}
    />
  );
}
```

Notes on the design:
- `CheckoutPage` is kept presentational — it takes `items`, `onBackToCart`, and `onPay` as props so it can plug into whatever cart/routing/payment logic your app already has.
- Validation runs on submit and shows inline errors per field; the Pay button disables while `onPay` is pending or the cart is empty.
- Layout is a two-column grid (summary + form) that collapses to one column under 720px.
